const MOBILE_STATES=new Set(['mobile-agenda','mobile-pending-detail','mobile-manual-booking','mobile-today','mobile-today-overdue','mobile-today-empty','mobile-request-list','mobile-request-detail','mobile-request-confirmed','mobile-request-rejected','mobile-alternative-date','mobile-alternative-slots','mobile-alternative-review','mobile-owner-decision-pending','mobile-booking-step-client','mobile-booking-step-schedule','mobile-booking-step-review','mobile-booking-invalid','mobile-client-search','mobile-quick-client','mobile-client-detail','mobile-stale','mobile-error','mobile-forbidden','mobile-loading','mobile-more']);
const mobileRoot=document.getElementById('mobile-crm'),mobileNav=document.querySelector('.mobile-crm-nav');
const mobileDraft={client:'Анна Ковалева',pet:'Барсик',service:'Первичный приём терапевта',staff:'Анна Иванова',date:'1 августа',time:'',price:'2 500 ₽',comment:'',dirty:false};
const mEsc=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const mobileState=state=>state==='mobile-agenda'?'mobile-today':state==='mobile-pending-detail'?'mobile-request-detail':state==='mobile-manual-booking'?'mobile-booking-step-client':state;
function mIcon(name){const icons={search:'search',calendar:'calendar',plus:'create',back:'back',more:'more',phone:'clients'};return `<svg class="vh-icon" aria-hidden="true"><use href="assets/icons.svg#${icons[name]||'more'}"></use></svg>`}
function mAppBar(title,{subtitle='VetHelp Садовая',back=null,plus=false,search=false}={}){return `<header class="m-appbar">${back?`<button class="m-back" data-mobile-go="${back}" aria-label="Назад">${mIcon('back')} <span>Назад</span></button>`:''}<div class="m-appbar-main"><small>${mEsc(subtitle)}</small><h1 tabindex="-1">${mEsc(title)}</h1></div><div class="m-appbar-actions">${search?`<button class="m-icon" data-mobile-action="focus-search" aria-label="Поиск" title="Поиск">${mIcon('search')}</button>`:''}${plus?`<button class="m-fab" data-mobile-go="mobile-booking-step-client" aria-label="Новая запись" title="Новая запись">${mIcon('plus')}</button>`:''}</div></header>`}
function mDateStrip(){const days=[['Пн','29'],['Вт','30'],['Ср','31'],['Сегодня','1'],['Пт','2'],['Сб','3'],['Вс','4']];return `<div class="m-date-strip" aria-label="Выбор даты">${days.map(([day,num],i)=>`<button class="m-date" data-mobile-action="date" aria-pressed="${i===3}" data-today="${i===3}"><span>${day}</span><strong>${num}</strong></button>`).join('')}<button class="m-date" data-mobile-action="calendar" aria-label="Открыть календарь"><span>${mIcon('calendar')}</span><strong>Дата</strong></button></div>`}
function mStatus(entry){const urgent=entry.kind==='overdue'||entry.kind==='pending';const label=entry.kind==='overdue'?'Просрочено · 02:14':entry.kind==='pending'?'Требует ответа · 00:38':entry.kind==='alternative'?'Ждёт владельца':'Подтверждена';return `<span class="m-status" ${urgent?'data-tone="urgent"':''}><span aria-hidden="true">${urgent?'!':'✓'}</span>${label}</span>`}
function mAgendaRow(entry){return `<button class="m-agenda-row" data-kind="${entry.kind}" data-mobile-go="${['overdue','pending'].includes(entry.kind)?'mobile-request-detail':'mobile-request-confirmed'}" aria-label="${mEsc(entry.time)}, ${mEsc(entry.pet)}, ${mEsc(entry.service)}, ${mEsc(entry.status)}"><span class="m-time">${entry.time}<small>${Math.round(entry.duration*30)} мин</small></span><h3>${mEsc(entry.pet)}</h3><span class="m-price">${entry.price}</span><span class="m-service">${mEsc(entry.service)}</span><span class="m-meta">${mEsc(entry.staff)}</span>${mStatus(entry)}</button>`}
function mAgenda(entries){const now='10:12',rows=entries.map(mAgendaRow),nextIndex=entries.findIndex(entry=>entry.time>now),marker='<div class="m-now">Сейчас · 10:12</div>';rows.splice(nextIndex<0?rows.length:nextIndex,0,marker);return rows.join('')}
function renderToday(state){const empty=state==='mobile-today-empty',overdue=state==='mobile-today-overdue'||state==='mobile-today';const entries=appState.entries.filter(e=>!['break','unavailable'].includes(e.kind)).sort((a,b)=>a.time.localeCompare(b.time));return `${mAppBar('Сегодня, 1 августа',{plus:true,search:true})}${mDateStrip()}<main class="m-content"><div class="m-summary"><span><strong>${empty?0:entries.length}</strong> записей</span><span><strong>${empty?0:3}</strong> требуют ответа</span><span><strong>${empty?0:1}</strong> просрочена</span></div>${empty?`<section class="m-state"><span class="m-state-icon">✓</span><h2>На сегодня записей нет</h2><p>Можно создать запись или выбрать другую дату.</p><button class="m-primary" data-mobile-go="mobile-booking-step-client">Новая запись</button></section>`:`${overdue?`<section class="m-urgent"><div class="m-urgent-head"><strong>Просрочена на 02:14</strong><span aria-hidden="true">!</span></div><p>Барсик · первичный приём<br>10:30 · Анна Иванова</p><button class="m-primary" data-mobile-go="mobile-request-detail">Открыть заявку</button></section>`:''}<div class="m-section-title"><h2>Расписание</h2><button class="m-link" data-mobile-go="mobile-request-list">Все заявки</button></div><section class="m-timeline" aria-label="Хронологическое расписание">${mAgenda(entries)}</section>`}</main>`}
function renderRequests(){const requests=appState.entries.filter(e=>['overdue','pending'].includes(e.kind)).sort((a,b)=>({overdue:0,pending:1}[a.kind]-{overdue:0,pending:1}[b.kind]));return `${mAppBar('Заявки',{plus:true,search:true})}<main class="m-content"><div class="m-segmented"><button aria-pressed="true">Требуют ответа</button><button aria-pressed="false">Все</button></div><div class="m-chips"><button class="m-chip" aria-pressed="true">Сегодня</button><button class="m-chip">Просроченные</button><button class="m-chip">Другие даты</button></div>${requests.map(e=>`<button class="m-request-row" data-mobile-go="mobile-request-detail"><h2>${e.pet} · ${e.time}</h2><span class="m-sla" ${e.kind==='pending'?'data-tone="soon"':''}>${e.kind==='overdue'?'−02:14':'00:38'}</span><p>${e.service}<br>${e.staff} · ${e.price} · ${e.source}</p></button>`).join('')}</main>`}
function renderDetail(state){const confirmed=state==='mobile-request-confirmed',rejected=state==='mobile-request-rejected',pending=!confirmed&&!rejected;const status=confirmed?'Подтверждена':rejected?'Отклонена':'Требует ответа';return `${mAppBar('Запись',{back:'mobile-today'})}<main><section class="m-detail-hero">${pending?'<span class="m-status" data-tone="urgent"><span aria-hidden="true">!</span>Требует ответа</span>':`<span class="m-status"><span aria-hidden="true">✓</span>${status}</span>`}<h2>Барсик</h2><p>Первичный приём терапевта</p><div class="m-detail-facts"><strong>10:30–11:00</strong><strong>2 500 ₽</strong><span>Анна Иванова</span><span>30 минут</span></div>${pending?'<div class="m-detail-sla">Просрочено на 02:14</div>':''}</section><section class="m-detail-section"><h2>Основное</h2><div class="m-definition"><span>Дата</span><strong>1 августа</strong></div><div class="m-definition"><span>Источник</span><strong>Сайт</strong></div></section><section class="m-detail-section"><h2>Клиент и питомец</h2><p><strong>Анна Ковалева</strong><br>Барсик · кот</p><div class="m-inline-actions"><button class="m-secondary" data-mobile-action="call">Позвонить</button><button class="m-secondary" data-mobile-go="mobile-client-detail">Открыть клиента</button></div></section><section class="m-detail-section"><h2>Комментарий</h2><p>Первичный осмотр, владелец просит подтвердить время.</p></section><section class="m-detail-section"><button class="m-disclosure" data-mobile-action="disclosure">История <span>›</span></button><button class="m-disclosure" data-mobile-action="disclosure">Дополнительно <span>›</span></button></section></main>${pending?`<footer class="m-task-footer"><button class="m-primary" data-mobile-action="confirm">Подтвердить</button><button class="m-secondary" data-mobile-go="mobile-alternative-date">Другое время</button><button class="m-tertiary m-danger" data-mobile-action="reject-menu" aria-label="Другие действия">•••</button></footer>`:`<footer class="m-task-footer single"><button class="m-primary" data-mobile-go="mobile-today">Вернуться в Сегодня</button></footer>`}`}
function renderAlternative(state){const stage=state==='mobile-alternative-date'?'date':state==='mobile-alternative-review'?'review':'slots';if(stage==='review')return `${mAppBar('Проверка',{back:'mobile-alternative-slots'})}<main class="m-flow-body"><h2>Предложить другое время</h2><div class="m-review"><div class="m-review-row"><span>Было</span><strong>1 августа · 10:30<br>Анна Иванова</strong></div><div class="m-review-row"><span>Предлагаем</span><strong>1 августа · 14:30<br>Мария Смирнова</strong></div><div class="m-review-row"><span>Цена</span><strong>2 500 ₽</strong></div><div class="m-review-row"><span>Причина</span><strong>Специалист недоступен</strong></div></div></main><footer class="m-task-footer single"><button class="m-primary" data-mobile-action="send-alternative">Отправить предложение</button></footer>`;const slots=[['Сегодня','14:30–15:00','Мария Смирнова'],['Сегодня','16:00–16:30','Анна Иванова'],['Завтра','09:30–10:00','Илья Петров']];return `${mAppBar(stage==='date'?'Дата и ограничения':'Доступное время',{back:stage==='date'?'mobile-request-detail':'mobile-alternative-date'})}<main class="m-flow-body"><div class="m-alt-original"><strong>Исходное время</strong><br>1 августа · 10:30 · Анна Иванова</div>${mDateStrip()}${stage==='date'?`<h2>Кого ищем</h2><button class="m-choice" aria-pressed="true"><span><strong>Любой терапевт</strong><small>Покажем ближайшее время</small></span><span>✓</span></button><button class="m-choice"><span><strong>Анна Иванова</strong><small>Сохранить текущего врача</small></span></button>`:`<section class="m-slot-group"><h2>Лучшие варианты</h2>${slots.map((s,i)=>`<button class="m-slot" data-mobile-action="slot" data-slot="${i}" aria-pressed="${i===0}"><span><strong>${s[0]} · ${s[1]}</strong><small>${s[2]} · доступно</small></span><strong>2 500 ₽</strong></button>`).join('')}<button class="m-secondary" data-mobile-action="all-slots">Посмотреть все интервалы</button></section>`}</main><footer class="m-task-footer single"><button class="m-primary" data-mobile-go="${stage==='date'?'mobile-alternative-slots':'mobile-alternative-review'}">Продолжить</button></footer>`}
function renderBooking(state){const step=state==='mobile-booking-step-schedule'?2:state==='mobile-booking-step-review'?3:1,invalid=state==='mobile-booking-invalid';if(step===3)return `${mAppBar('Проверка',{back:'mobile-booking-step-schedule'})}<header class="m-flow-head"><strong>Шаг 3 из 3</strong><div class="m-progress"><span style="width:100%"></span></div></header><main class="m-flow-body"><h2>Проверьте запись</h2><div class="m-review"><div class="m-review-row"><span>Клиент</span><strong>${mobileDraft.client}</strong></div><div class="m-review-row"><span>Питомец</span><strong>${mobileDraft.pet}</strong></div><div class="m-review-row"><span>Услуга</span><strong>${mobileDraft.service}</strong></div><div class="m-review-row"><span>Врач</span><strong>${mobileDraft.staff}</strong></div><div class="m-review-row"><span>Дата и время</span><strong>${mobileDraft.date} · ${mobileDraft.time||'14:30'}</strong></div><div class="m-review-row"><span>Цена</span><strong>${mobileDraft.price}</strong></div></div><label class="m-field"><span>Комментарий</span><textarea data-draft="comment" placeholder="Необязательно">${mobileDraft.comment}</textarea></label></main><footer class="m-task-footer"><button class="m-secondary" data-mobile-go="mobile-booking-step-schedule">Назад</button><button class="m-primary" data-mobile-action="create-booking">Создать запись</button><span></span></footer>`;if(step===2)return `${mAppBar('Новая запись',{back:'mobile-booking-step-client'})}<header class="m-flow-head"><strong>Шаг 2 из 3</strong><div class="m-progress"><span style="width:66%"></span></div></header><main class="m-flow-body"><h2>Запись</h2><button class="m-choice" aria-pressed="true"><span><strong>${mobileDraft.service}</strong><small>Цена 2 500 ₽</small></span><span>✓</span></button><button class="m-choice" aria-pressed="true"><span><strong>${mobileDraft.staff}</strong><small>Терапевт</small></span><span>›</span></button><div class="m-slot-group"><h2>Доступное время · 1 августа</h2>${['14:30','15:30','16:00'].map(t=>`<button class="m-slot" data-mobile-action="booking-slot" data-time="${t}" aria-pressed="${mobileDraft.time===t}"><span><strong>${t}–${t==='14:30'?'15:00':'16:30'}</strong><small>Доступно</small></span></button>`).join('')}</div>${invalid?'<p class="m-error">Выберите доступное время</p>':''}</main><footer class="m-task-footer single"><button class="m-primary" data-mobile-action="booking-next" ${mobileDraft.time?'':'disabled'}>Продолжить</button></footer>`;return `${mAppBar('Новая запись',{back:'mobile-today'})}<header class="m-flow-head"><strong>Шаг 1 из 3</strong><div class="m-progress"><span style="width:33%"></span></div></header><main class="m-flow-body"><h2>Клиент и питомец</h2><label class="m-field"><span>Найти клиента</span><input id="mobile-client-input" type="search" value="${mobileDraft.client}" inputmode="search" autocomplete="off"></label><button class="m-result" aria-pressed="true"><span><strong>${mobileDraft.client}</strong><small>+7 ••• •••-14-20 · 2 питомца</small></span><span>✓</span></button><button class="m-result" aria-pressed="true"><span><strong>${mobileDraft.pet}</strong><small>Кот · 4 года</small></span><span>✓</span></button><button class="m-link" data-mobile-go="mobile-quick-client">+ Создать нового клиента</button></main><footer class="m-task-footer single"><button class="m-primary" data-mobile-go="mobile-booking-step-schedule">Продолжить</button></footer>`}
function renderBookingInvalid(){return renderBooking('mobile-booking-step-schedule').replace('<div class="m-slot-group">','<div class="m-slot-group" tabindex="0" aria-describedby="booking-time-error" aria-invalid="true">').replace('</div></main>','</div><p id="booking-time-error" class="m-error" role="alert">Выберите доступное время</p></main>')}
function renderQuickClient(){return `${mAppBar('Новый клиент',{back:'mobile-booking-step-client'})}<main class="m-flow-body"><label class="m-field"><span>Имя владельца</span><input data-quick="owner" value="Ольга Демина" autocomplete="name"></label><label class="m-field"><span>Телефон</span><input data-quick="phone" value="+7 921 555-18-40" inputmode="tel"></label><label class="m-field"><span>Имя питомца</span><input data-quick="pet" value="Кекс"></label><label class="m-field"><span>Вид питомца</span><select data-quick="species"><option>Кошка</option><option>Собака</option></select></label></main><footer class="m-task-footer"><button class="m-secondary" data-mobile-go="mobile-booking-step-client">Отмена</button><button class="m-primary" data-mobile-action="save-client">Сохранить клиента</button><span></span></footer>`}
function renderClients(state){if(state==='mobile-client-detail')return `${mAppBar('Клиент',{back:'mobile-client-search',plus:true})}<main><section class="m-detail-hero"><h2>Анна Ковалева</h2><p>+7 ••• •••-14-20 · 2 питомца</p><div class="m-inline-actions"><button class="m-secondary">Позвонить</button><button class="m-primary" data-mobile-go="mobile-booking-step-client">Новая запись</button></div></section><section class="m-detail-section"><h2>Питомцы</h2><p><strong>Барсик</strong> · кот, 4 года</p><p><strong>Марс</strong> · пёс, 6 лет</p></section><section class="m-detail-section"><h2>Ближайшая запись</h2><p>Барсик · 1 августа, 10:30<br>Первичный приём</p></section><section class="m-detail-section"><button class="m-disclosure">История <span>›</span></button></section></main>`;return `${mAppBar('Клиенты',{plus:true})}<div class="m-search"><input id="mobile-search" type="search" placeholder="Имя, телефон или питомец" inputmode="search"></div><main class="m-content"><h2>Недавние</h2>${[['Анна Ковалева','Барсик, Марс · сегодня 10:30'],['Олег Миронов','Луна · 4 августа'],['Ирина Соколова','Боня · 8 августа']].map(c=>`<button class="m-client-row" data-mobile-go="mobile-client-detail"><span><strong>${c[0]}</strong><small>+7 ••• •••-14-20</small></span><small>${c[1]}</small></button>`).join('')}</main>`}
function renderMore(){return `${mAppBar('Ещё')}<main class="m-content"><button class="m-disclosure">Сотрудники <span>›</span></button><button class="m-disclosure">Настройки <span>›</span></button><button class="m-disclosure">Сменить локацию <span>›</span></button><button class="m-disclosure">Профиль <span>›</span></button><section class="m-detail-section"><strong>Интерактивный прототип</strong><p>Данные и действия демонстрационные.</p></section></main>`}
function renderSystem(state){const map={'mobile-stale':['Последние доступные данные','Обновление не удалось. Показана версия от 14:32.','Повторить'],'mobile-error':['Не удалось загрузить','Проверьте соединение и повторите попытку.','Повторить'],'mobile-forbidden':['Нет доступа','Эта локация недоступна для текущей роли.','Вернуться'],'mobile-loading':['Загружаем расписание','Это займёт несколько секунд.','']};const [title,text,cta]=map[state];return `${mAppBar('Сегодня')}<main class="m-state">${state==='mobile-loading'?'<span class="m-spinner" aria-label="Загрузка"></span>':'<span class="m-state-icon">!</span>'}<h2>${title}</h2><p>${text}</p>${cta?`<button class="m-primary" data-mobile-go="mobile-today">${cta}</button>`:''}</main>`}
function normalizeMobileLandmarks(state){if(state!=='mobile-owner-decision-pending')return;const section=mobileRoot.querySelector(':scope > .m-state');if(!section)return;const main=document.createElement('main');main.className=section.className;main.append(...section.childNodes);section.replaceWith(main)}
function renderMobileCRM(requested=appState.state){const state=mobileState(requested),task=['mobile-request-detail','mobile-request-confirmed','mobile-request-rejected','mobile-alternative-date','mobile-alternative-slots','mobile-alternative-review','mobile-owner-decision-pending','mobile-booking-step-client','mobile-booking-step-schedule','mobile-booking-step-review','mobile-booking-invalid','mobile-quick-client'].includes(state);mobileRoot.hidden=false;mobileNav.hidden=task;mobileRoot.dataset.task=String(task);let html;if(['mobile-today','mobile-today-overdue','mobile-today-empty'].includes(state))html=renderToday(state);else if(state==='mobile-request-list')html=renderRequests();else if(['mobile-request-detail','mobile-request-confirmed','mobile-request-rejected'].includes(state))html=renderDetail(state);else if(['mobile-alternative-date','mobile-alternative-slots','mobile-alternative-review'].includes(state))html=renderAlternative(state);else if(state==='mobile-owner-decision-pending')html=`${mAppBar('Предложение отправлено',{back:'mobile-today'})}<section class="m-state"><span class="m-state-icon">✓</span><h2>Ждём решения владельца</h2><p>Предложено 1 августа, 14:30 · Мария Смирнова.</p><button class="m-primary" data-mobile-go="mobile-today">Вернуться в Сегодня</button></section>`;else if(['mobile-booking-step-client','mobile-booking-step-schedule','mobile-booking-step-review','mobile-booking-invalid'].includes(state))html=renderBooking(state);else if(state==='mobile-quick-client')html=renderQuickClient();else if(['mobile-client-search','mobile-client-detail'].includes(state))html=renderClients(state);else if(state==='mobile-more')html=renderMore();else if(['mobile-stale','mobile-error','mobile-forbidden','mobile-loading'].includes(state))html=renderSystem(state);else html=renderToday('mobile-today');mobileRoot.innerHTML=html;mobileNav.hidden=task;mobileNav.querySelectorAll('[data-mobile-nav]').forEach(button=>{const target=button.dataset.mobileNav;const active=target==='mobile-today'&&state.startsWith('mobile-today')||target==='mobile-request-list'&&state.startsWith('mobile-request')||target==='mobile-client-search'&&state.startsWith('mobile-client')||target==='mobile-more'&&state==='mobile-more';button.toggleAttribute('aria-current',active);if(active)button.setAttribute('aria-current','page')});announce(`Открыт экран ${state}`)}
function mobileGo(state){appState.state=state;setUrl(state);app.dataset.state=state;renderMobileCRM(state);if(state==='mobile-booking-invalid'){mobileRoot.innerHTML=renderBookingInvalid();mobileNav.hidden=true}normalizeMobileLandmarks(state);scrollTo({top:0,behavior:'auto'});requestAnimationFrame(()=>mobileRoot.querySelector(state==='mobile-booking-invalid'?'.m-slot-group':'h1')?.focus())}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-mobile-nav]');if(nav){mobileGo(nav.dataset.mobileNav);return}const go=event.target.closest('[data-mobile-go]');if(go){mobileGo(go.dataset.mobileGo);return}const action=event.target.closest('[data-mobile-action]');if(!action)return;const name=action.dataset.mobileAction;if(name==='focus-search')document.getElementById('mobile-search')?.focus();else if(name==='confirm'){mobileGo('mobile-request-confirmed');announce('Заявка подтверждена')}else if(name==='reject-menu'){action.innerHTML='Отклонить';action.dataset.mobileAction='reject'}else if(name==='reject'){mobileGo('mobile-request-rejected')}else if(name==='send-alternative'){mobileGo('mobile-owner-decision-pending')}else if(name==='booking-slot'){document.querySelectorAll('[data-mobile-action=booking-slot]').forEach(x=>x.setAttribute('aria-pressed','false'));action.setAttribute('aria-pressed','true');mobileDraft.time=action.dataset.time;mobileDraft.dirty=true;document.querySelector('[data-mobile-action=booking-next]').disabled=false}else if(name==='booking-next'){mobileGo(mobileDraft.time?'mobile-booking-step-review':'mobile-booking-invalid')}else if(name==='create-booking'){mobileGo('mobile-request-confirmed');announce('Запись создана')}else if(name==='save-client'){mobileDraft.client=document.querySelector('[data-quick=owner]').value;mobileDraft.pet=document.querySelector('[data-quick=pet]').value;mobileDraft.dirty=true;mobileGo('mobile-booking-step-client');announce('Клиент сохранён и выбран')}else if(name==='date'){document.querySelectorAll('.m-date').forEach(x=>x.setAttribute('aria-pressed','false'));action.setAttribute('aria-pressed','true')}else if(name==='slot'){document.querySelectorAll('[data-mobile-action=slot]').forEach(x=>x.setAttribute('aria-pressed','false'));action.setAttribute('aria-pressed','true')}else if(name==='calendar')announce('Календарь открыт в bounded prototype state');else if(name==='call')announce('Вызов телефона не выполняется в прототипе')});
document.addEventListener('input',event=>{if(event.target.matches('[data-draft]')){mobileDraft[event.target.dataset.draft]=event.target.value;mobileDraft.dirty=true}});
window.addEventListener('popstate',()=>renderMobileCRM(new URLSearchParams(location.search).get('state')||'mobile-today'));
if(MOBILE_STATES.has(requestedState)||matchMedia('(max-width:599px)').matches){renderMobileCRM(requestedState);if(requestedState==='mobile-booking-invalid'){mobileRoot.innerHTML=renderBookingInvalid();mobileNav.hidden=true;requestAnimationFrame(()=>mobileRoot.querySelector('.m-slot-group')?.focus())}normalizeMobileLandmarks(requestedState)}
